def algorithm(func, dim, lb, ub, budget, rng):
    x = np.zeros(dim)
    v = np.zeros(dim)
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        for i in range(dim):
            r1 = 2 * rng.rand() - 1
            r2 = 2 * rng.rand() - 1

            if rng.rand() < 0.5:
                v[i] *= 0.9
            else:
                x[i] += r1 * 0.05 * (ub - lb)
                x[i] = np.clip(x[i], lb, ub)
                v[i] = r2 * 0.1 * (x[i] - best_x[i])

        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x.copy()

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    T = 1e6
    x_best = rng.uniform(lb, ub, size=dim)
    f_best = func(x_best)

    for _ in range(budget):
        sigma = max(T / (_ + 1), 1e-3) * np.random.normal(0, 1, size=dim)
        x_candidate = x_best + sigma * rng.uniform(lb, ub, size=dim)

        f_candidate = func(np.clip(x_candidate, lb, ub))

        if f_candidate < f_best:
            x_best = x_candidate
            f_best = f_candidate

        T *= 0.9999

    return np.array([x_best])
